# About page and Downloads page. key -> (en, sw, fr)
S = {
"about.meta_title": ("About · Pleadli", "Kuhusu · Pleadli", "À propos · Pleadli"),
"about.meta_description": ("Pleadli exists to provide the digital infrastructure that makes justice institutions work together without becoming the same institution: software built for each participant's own work, connected only where a legitimate relationship exists.", "Pleadli ipo kutoa miundombinu ya kidijitali inayowezesha taasisi za haki kufanya kazi pamoja bila kuwa taasisi moja: programu iliyojengwa kwa kazi ya kila mshiriki, ikiunganishwa pale tu uhusiano halali upo.", "Pleadli existe pour fournir l'infrastructure numérique qui permet aux institutions judiciaires de travailler ensemble sans devenir une seule institution : des logiciels conçus pour le travail propre de chacun, reliés seulement là où existe une relation légitime."),
"about.badge": ("About", "Kuhusu", "À propos"),
"about.lead": ("Pleadli exists to provide the digital infrastructure that makes that possible: software built for each participant's own work, connected only where a legitimate relationship exists.", "Pleadli ipo kutoa miundombinu ya kidijitali inayowezesha hilo: programu iliyojengwa kwa kazi ya kila mshiriki, ikiunganishwa pale tu uhusiano halali upo.", "Pleadli existe pour fournir l'infrastructure numérique qui rend cela possible : des logiciels conçus pour le travail propre de chacun, reliés seulement là où existe une relation légitime."),
"about.principles.identity.title": ("One case, one identity", "Shauri moja, utambulisho mmoja", "Une affaire, une identité"),
"about.principles.identity.body": ("A case keeps the same identity from investigation through to custody.", "Shauri hubaki na utambulisho ule ule tangu upelelezi hadi kizuizini.", "Une affaire garde la même identité de l'enquête jusqu'à la détention."),
"about.principles.owned.title": ("Institution-owned records", "Kumbukumbu zinazomilikiwa na taasisi", "Des dossiers détenus par l'institution"),
"about.principles.owned.body": ("Each application's records stay with the institution that created them, always.", "Kumbukumbu za kila programu hubaki kwa taasisi iliyoziunda, daima.", "Les dossiers de chaque application restent toujours à l'institution qui les a créés."),
"about.principles.reference.title": ("Referenceable, not visible", "Hurejelewa, haionekani", "Référençable, pas visible"),
"about.principles.reference.body": ("Other applications can reference a case without seeing inside it.", "Programu nyingine zinaweza kurejelea shauri bila kuona ndani yake.", "D'autres applications peuvent référencer une affaire sans voir à l'intérieur."),
"about.pillars.fragmentation.title": ("Justice without fragmentation", "Haki bila mgawanyiko", "Une justice sans fragmentation"),
"about.pillars.fragmentation.p1": ("A single matter can pass through police, prosecution, courts, and prisons, and today each of those stages usually runs on its own paperwork, with almost nothing connecting them. The same facts get re-entered at every handoff, and nobody outside one institution can confirm where a case actually stands.", "Shauri moja linaweza kupita polisi, mashtaka, mahakama na magereza, na leo kila hatua kati ya hizo kwa kawaida huendeshwa kwa makaratasi yake, bila karibu chochote kinachoziunganisha. Ukweli ule ule huandikwa upya kila linapokabidhiwa, na hakuna aliye nje ya taasisi moja anayeweza kuthibitisha shauri limefikia wapi.", "Une même affaire peut passer par la police, le parquet, les tribunaux et les prisons, et aujourd'hui chacune de ces étapes fonctionne d'ordinaire avec ses propres papiers, presque sans lien entre elles. Les mêmes faits sont ressaisis à chaque passage, et personne hors d'une institution ne peut confirmer où en est réellement l'affaire."),
"about.pillars.fragmentation.p2": ("Pleadli exists so institutions don't have to recreate the same context every time a matter crosses a boundary.", "Pleadli ipo ili taasisi zisilazimike kuunda upya muktadha ule ule kila shauri linapovuka mpaka.", "Pleadli existe pour que les institutions n'aient pas à reconstituer le même contexte chaque fois qu'une affaire franchit une frontière."),
"about.pillars.centralization.title": ("Connection without centralization", "Muunganiko bila kuweka kila kitu kati", "Relier sans centraliser"),
"about.pillars.centralization.p1": ("Connecting institutions doesn't mean putting all their records into one shared database. A case gets a continuous identity that follows it across the whole process, but what stays separate is who owns the records: police records belong to police, prosecution decisions belong to the DPP, and so on.", "Kuunganisha taasisi hakumaanishi kuweka kumbukumbu zao zote kwenye hifadhidata moja ya pamoja. Shauri hupata utambulisho endelevu unaolifuata katika mchakato mzima, lakini kinachobaki tofauti ni nani anamiliki kumbukumbu: kumbukumbu za polisi ni za polisi, maamuzi ya mashtaka ni ya DPP, na kadhalika.", "Relier les institutions ne veut pas dire mettre tous leurs dossiers dans une seule base partagée. Une affaire reçoit une identité continue qui la suit tout au long du processus, mais ce qui reste séparé, c'est qui détient les dossiers : les dossiers de police appartiennent à la police, les décisions de poursuite au DPP, et ainsi de suite."),
"about.pillars.purpose.title": ("Purpose-built software", "Programu iliyojengwa kwa kusudi lake", "Des logiciels faits pour leur usage"),
"about.pillars.purpose.p1": ("Police software should feel like police software. DPP software should feel like prosecution software. Court software should feel like court software. A lawyer's software should feel like legal practice software. Prison software should feel like custody software.", "Programu ya polisi inapaswa kuhisi kama programu ya polisi. Programu ya DPP inapaswa kuhisi kama programu ya mashtaka. Programu ya mahakama inapaswa kuhisi kama programu ya mahakama. Programu ya wakili inapaswa kuhisi kama programu ya uwakili. Programu ya magereza inapaswa kuhisi kama programu ya ulinzi wa wafungwa.", "Un logiciel de police doit ressembler à un logiciel de police. Celui du DPP, à un logiciel de poursuites. Celui d'un tribunal, à un logiciel de tribunal. Celui d'un avocat, à un logiciel de cabinet. Celui d'une prison, à un logiciel de détention."),
"about.pillars.purpose.p2": ("Pleadli Police, Pleadli DPP, Pleadli Courts, Pleadli Lawyers, and Pleadli Prisons are separate applications, each designed around the work its users actually do, not one dashboard reused everywhere.", "Pleadli Police, Pleadli DPP, Pleadli Courts, Pleadli Lawyers na Pleadli Prisons ni programu tofauti, kila moja imeundwa kuzunguka kazi wanayofanya watumiaji wake kweli, si dashibodi moja inayotumika kila mahali.", "Pleadli Police, Pleadli DPP, Pleadli Courts, Pleadli Lawyers et Pleadli Prisons sont des applications distinctes, chacune conçue autour du travail réel de ses utilisateurs, pas un seul tableau de bord réutilisé partout."),
"about.pillars.thread.title": ("One continuous thread", "Uzi mmoja endelevu", "Un fil continu"),
"about.pillars.thread.p1": ("Responsibility for a matter moves: from an investigating officer, to a prosecutor, to a court, sometimes to a lawyer representing one side. Pleadli lets the underlying matter keep continuity even as that responsibility, and the professionals involved, change.", "Wajibu wa shauri huhama: kutoka kwa afisa mpelelezi, kwenda kwa mwendesha mashtaka, kwenda mahakamani, wakati mwingine kwa wakili anayewakilisha upande mmoja. Pleadli huruhusu shauri lenyewe kubaki na mwendelezo hata wajibu huo, na wataalamu wanaohusika, wanapobadilika.", "La responsabilité d'une affaire se déplace : de l'enquêteur au procureur, puis au tribunal, parfois à l'avocat d'une des parties. Pleadli permet à l'affaire elle-même de garder sa continuité même quand cette responsabilité, et les professionnels concernés, changent."),
"about.pillars.uganda.title": ("Built from Uganda outward", "Imejengwa kuanzia Uganda kwenda nje", "Construit à partir de l'Ouganda"),
"about.pillars.uganda.p1": ("Pleadli is starting with Uganda, designed around the justice system as it actually operates here, not a generic template applied to any country.", "Pleadli inaanza na Uganda, imeundwa kuzunguka mfumo wa haki jinsi unavyofanya kazi hapa kweli, si kiolezo cha jumla kinachowekwa kwa nchi yoyote.", "Pleadli commence par l'Ouganda, conçu autour du système judiciaire tel qu'il fonctionne réellement ici, pas un modèle générique appliqué à n'importe quel pays."),
"about.first_note": ("Pleadli Police and Pleadli DPP were built first because investigation, referral, perusal, and prosecution form a useful early end-to-end connection, not because Courts, Lawyers, and Prisons are later stages of the same product. They are separate applications, each built around its own requirements.", "Pleadli Police na Pleadli DPP zilijengwa kwanza kwa sababu upelelezi, upelekaji, upitiaji na mashtaka huunda muunganiko mzuri wa mwanzo hadi mwisho, si kwa sababu Courts, Lawyers na Prisons ni hatua za baadaye za bidhaa ile ile. Ni programu tofauti, kila moja imejengwa kuzunguka mahitaji yake.", "Pleadli Police et Pleadli DPP ont été construits en premier parce que l'enquête, la transmission, l'examen et les poursuites forment une première liaison utile de bout en bout, et non parce que Courts, Lawyers et Prisons seraient des étapes ultérieures du même produit. Ce sont des applications distinctes, chacune construite autour de ses propres besoins."),
"about.sign_in_title": ("Sign in to Pleadli", "Ingia kwenye Pleadli", "Se connecter à Pleadli"),
"about.sign_in_body": ("Institutional users sign in to Pleadli to manage their organization, structure, and staff.", "Watumiaji wa taasisi huingia kwenye Pleadli kusimamia shirika lao, muundo wake na wafanyakazi.", "Les utilisateurs institutionnels se connectent à Pleadli pour gérer leur organisation, sa structure et son personnel."),
"downloads.title": ("Download Pleadli for Windows.", "Pakua Pleadli kwa Windows.", "Télécharger Pleadli pour Windows."),
"downloads.lead": ("Police, DPP, Lawyers and Prisons have their first Windows release. Once installed, each checks for a signed update and offers to install it; nothing is installed without asking. These are early releases, in active development and not yet field-validated. Courts is not released yet.", "Police, DPP, Lawyers na Prisons zina toleo lao la kwanza la Windows. Ikishasakinishwa, kila moja hutafuta sasisho lililotiwa saini na hukuomba kulisakinisha; hakuna kinachosakinishwa bila kuuliza. Haya ni matoleo ya mapema, yanaendelea kuundwa na bado hayajathibitishwa kazini. Courts bado haijatolewa.", "Police, DPP, Lawyers et Prisons ont leur première version Windows. Une fois installée, chacune vérifie s'il existe une mise à jour signée et propose de l'installer ; rien n'est installé sans votre accord. Ce sont des versions précoces, en développement actif et pas encore validées sur le terrain. Courts n'est pas encore publié."),
"downloads.not_available": ("Not available", "Haipatikani", "Non disponible"),
"downloads.stand_title": ("Where the releases stand", "Matoleo yamefikia wapi", "Où en sont les versions"),
"downloads.stand.installers": ("Built: Windows installers (.msi and setup .exe), built and published by an automated release workflow.", "Imejengwa: visakinishi vya Windows (.msi na setup .exe), vinavyojengwa na kuchapishwa na mtiririko wa kiotomatiki wa matoleo.", "Fait : installateurs Windows (.msi et setup .exe), construits et publiés par un processus de publication automatisé."),
"downloads.stand.updates": ("Built: automatic updates, signed. An installed copy accepts only an update signed with Pleadli’s key.", "Imejengwa: masasisho ya kiotomatiki yaliyotiwa saini. Nakala iliyosakinishwa hupokea tu sasisho lililotiwa saini kwa ufunguo wa Pleadli.", "Fait : mises à jour automatiques, signées. Une copie installée n'accepte qu'une mise à jour signée avec la clé de Pleadli."),
"downloads.stand.codesign": ("Not yet: code-signed installers. Windows shows “Windows protected your PC” on first install; choose “More info”, then “Run anyway”.", "Bado: visakinishi vilivyotiwa saini ya msimbo. Windows huonyesha “Windows protected your PC” mara ya kwanza; chagua “More info”, kisha “Run anyway”.", "Pas encore : installateurs signés numériquement. Windows affiche « Windows a protégé votre ordinateur » à la première installation ; choisissez « Informations complémentaires », puis « Exécuter quand même »."),
"downloads.stand.rest": ("Not yet: published checksums, Linux and macOS installers, and a release of Pleadli Courts.", "Bado: checksum zilizochapishwa, visakinishi vya Linux na macOS, na toleo la Pleadli Courts.", "Pas encore : sommes de contrôle publiées, installateurs Linux et macOS, et une version de Pleadli Courts."),
}
